<?php

namespace Tests\Feature;

use App\User;
use Illuminate\Foundation\Testing\DatabaseTransactions;
use Tests\TestCase;

/**
 * Batch 2026-10-28 (exam-timetable round 17) — teacher admit-card print
 * scoping. Distinct from the round-7 "teacher myCard" rule (a teacher's
 * OWN admit card): this probes a teacher printing a STUDENT's card.
 *
 * Code read first (AdmitCardController::__construct): the staff screens
 * are gated teamSA, NOT teamSAT, by explicit owner ruling 2026-10-22 —
 * "admit cards are generated by the school office (teamSA) and
 * collected by the student/parent self-service below — teachers no
 * longer open the staff screens at all", because the former teamSAT
 * allowance let any teacher print any student's card through myCard.
 * myCard() itself aborts 403 for anyone who is not the student, the
 * student's parent, or teamSA.
 *
 * Expected shape (locked here, not "fixed"): a teacher is closed out
 * of student admit prints entirely — own class AND foreign class,
 * bulk AND single-student (?student=) AND self-service — while admin
 * prints and student/parent self-service keep working. If teachers
 * should print their own class's cards for exam-hall use, that is a
 * DESIGN QUESTION for the owner (open teamSA to teamSAT-scoped
 * teachers), not a defect: opening it without a scope check would
 * restore the exact leak the 2026-10-22 ruling closed.
 *
 * Anchors: teacher@ = Ananya Sharma (id 4), scope [1,4,7,10,13,8] —
 * class 1 (Prep) is own, class 2 (Class 1) is truly foreign. Student
 * 57 (Aarav, Prep, record 1) is own-class; student 100 is a real
 * student in class 1 with my_parent_id NULL (genuine foreign-parent
 * proof pattern from round 11). Aarav carries no owing record, so no
 * fee-defaulter block interferes with the self-service controls.
 * Exam 1 = Term 1 Examination 2026-2027 (current session).
 */
class OwnerExamTeacherAdmitPrintR17Test extends TestCase
{
    use DatabaseTransactions;

    protected function user($email)
    {
        return User::where('email', $email)->firstOrFail();
    }

    protected function teacher()
    {
        return $this->user('teacher@hackstra.app');
    }

    public function test_teacher_bulk_print_own_class_is_closed()
    {
        $this->actingAs($this->teacher())
            ->get(route('admit_cards.print', ['exam' => 1, 'class' => 1]))
            ->assertRedirect(route('login'));
    }

    public function test_teacher_bulk_print_foreign_class_is_closed()
    {
        $this->actingAs($this->teacher())
            ->get(route('admit_cards.print', ['exam' => 1, 'class' => 2]))
            ->assertRedirect(route('login'));
    }

    public function test_teacher_single_student_print_via_query_is_closed()
    {
        // ?student= narrows the bulk sheet to one card; the teamSA
        // gate fires before the roster is even built, so a teacher
        // cannot reach a single own-class student's card this way.
        $this->actingAs($this->teacher())
            ->get(route('admit_cards.print', ['exam' => 1, 'class' => 1, 'student' => 57]))
            ->assertRedirect(route('login'));
    }

    public function test_teacher_admit_index_is_closed()
    {
        $this->actingAs($this->teacher())
            ->get(route('admit_cards.index'))
            ->assertRedirect(route('login'));
    }

    public function test_teacher_self_service_card_is_403_and_list_redirects()
    {
        $this->actingAs($this->teacher())
            ->get(route('admit_cards.my_card', ['exam' => 1, 'student_id' => 57]))
            ->assertForbidden();

        $this->actingAs($this->teacher())
            ->get(route('admit_cards.my'))
            ->assertRedirect(route('dashboard'));
    }

    public function test_principal_admit_print_is_closed_like_teacher()
    {
        // Companion observation: the limited principal role reads
        // date sheets but is not teamSA, so the office admit screens
        // close for principals too (302 on staff screens, 403 on
        // self-service card). Locked so a future gate widening that
        // accidentally admits principals fails loudly.
        $this->actingAs($this->user('principal@hackstra.app'))
            ->get(route('admit_cards.print', ['exam' => 1, 'class' => 1]))
            ->assertRedirect(route('login'));

        $this->actingAs($this->user('principal@hackstra.app'))
            ->get(route('admit_cards.my_card', ['exam' => 1, 'student_id' => 57]))
            ->assertForbidden();
    }

    public function test_admin_bulk_print_and_self_service_still_open()
    {
        $this->actingAs($this->user('admin@hackstra.app'))
            ->get(route('admit_cards.print', ['exam' => 1, 'class' => 1]))
            ->assertOk();

        $this->actingAs($this->user('student@hackstra.app'))
            ->get(route('admit_cards.my_card', ['exam' => 1, 'student_id' => 57]))
            ->assertOk();

        $this->actingAs($this->user('parent@hackstra.app'))
            ->get(route('admit_cards.my_card', ['exam' => 1, 'student_id' => 57]))
            ->assertOk();
    }
}
